 "Jádro CAD bylo spuštěno znovu": "The CAD kernel was restarted",
 "Jádro CAD spadlo ({0}) a bylo spuštěno znovu. Zkuste operaci zopakovat; pokud se pád opakuje, model je pravděpodobně poškozený nebo příliš velký.": "The CAD kernel crashed ({0}) and was restarted. Try the operation again; if the crash repeats, the model is probably damaged or too large.",
