 "Ostatní (volné)": "Other (free-form)",
 "Ostatní části programu fungují dál: nabídky, nápověda, nastavení, otevření a uložení souborů, 2D skica i výkresy. Jen se nezobrazí 3D model.": "The rest of the program keeps working: menus, help, settings, opening and saving files, the 2D sketch and drawings. Only the 3D model is not displayed.",
 "Ostatní části programu fungují dál: nabídky, nápověda, nastavení, otevření a uložení souborů, 2D skica i výkresy. Model se místo 3D okna zobrazuje jako zjednodušený náhled: pohledy, přizpůsobení, přiblížení, otáčení i řez fungují, výběr ploch a hran kliknutím ne – použijte seznamy ve formulářích prvků a textové příkazy.": "The rest of the program keeps working: menus, help, settings, opening and saving files, the 2D sketch and drawings. Instead of the 3D window the model is shown as a simplified preview: views, fit, zoom, rotation and the section view work, selecting faces and edges by clicking does not – use the lists in the feature forms and text commands.",
