 "poloměr": "radius",
 "Poloměr": "Radius",
 "Poloměr / velikost": "Radius / size",
 "Poloměr = polovina vzdálenosti rovnoběžných bočních ploch; prostřední plocha se nahradí válcem tečným k oběma. Prostřední plochu lze vynechat, je-li mezi bočními plochami jediná. Obdélníková prostřední plocha kolmá na boční se zaoblí přesně, jiná přibližně.": "Radius = half the distance between the parallel side faces; the middle face is replaced by a cylinder tangent to both. The middle face can be omitted if there is only one between the side faces. A rectangular middle face perpendicular to the sides is rounded exactly, others approximately.",
 "poloměr = povrch, kde závit začíná: válec, nebo díra (jádro); hloubka jde do materiálu": "radius = the surface where the thread starts: the cylinder, or the hole (minor diameter); the depth goes into the material",
 "Poloměr kótovacího oblouku [mm]": "Dimension arc radius [mm]",
 "Poloměr kruhového profilu musí být kladný.": "The circular profile radius must be positive.",
 "Poloměr musí být kladný.": "The radius must be positive.",
 "Poloměr na konci R2": "End radius R2",
 "Poloměr na začátku R1": "Start radius R1",
 "Poloměr opsané": "Circumscribed radius",
 "Poloměr osy": "Centreline radius",
 "Poloměr se mění lineárně od začátku hrany (R1) k jejímu konci (R2). Začátek hrany určuje model – běží-li přechod obráceně, hodnoty prohoďte. Eliptické (asymetrické) zaoblení s různou vzdáleností na každé ploše jádro OCCT neumí.": "The radius changes linearly from the edge start (R1) to its end (R2). The edge start is defined by the model – if the blend runs the other way, swap the values. The OCCT kernel does not support elliptic (asymmetric) fillets with a different distance on each face.",
 "poloměr se po hraně mění od R1 k R2": "the radius changes along the edge from R1 to R2",
