 "Pracujete-li přes vzdálenou plochu (RDP), Citrix nebo ve virtuálním stroji, otevřete CAD přímo na počítači s grafickou kartou – vzdálené relace WebGL často neposkytují.": "If you work over Remote Desktop (RDP), Citrix or in a virtual machine, open the CAD directly on a computer with a graphics card – remote sessions often do not provide WebGL.",
